[CmdletBinding()]
param([string]$ConfigPath=(Join-Path $PSScriptRoot 'config.json'),[switch]$CheckGoogleDrive)
$ErrorActionPreference='Stop';$results=[System.Collections.Generic.List[object]]::new()
function AddCheck($name,$ok,$detail){$results.Add([pscustomobject]@{check=$name;ok=[bool]$ok;detail=$detail})}
$win=$PSVersionTable.PSVersion.Major -ge 7 -and [Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT;AddCheck 'Windows-PowerShell' $win "$([Environment]::OSVersion.Version); PowerShell $($PSVersionTable.PSVersion)"
try{$c=Get-Content -Raw $ConfigPath|ConvertFrom-Json;AddCheck 'config-json' $true 'Parsed'}catch{$c=$null;AddCheck 'config-json' $false 'Missing or invalid configuration'}
if($c){foreach($p in @($c.paths.pgDump,$c.paths.rclone)){AddCheck "tool-$([IO.Path]::GetFileName($p))" (Test-Path $p) 'Configured path exists'};$root=$c.paths.root;try{$drive=Get-PSDrive -Name ([IO.Path]::GetPathRoot($root).TrimEnd(':\'));AddCheck 'disk-space' ($drive.Free -ge 5GB) 'Requires at least 5 GB free'}catch{AddCheck 'disk-space' $false 'Drive unavailable'};AddCheck 'production-identity-config' ($c.database.name -eq 'leadconnect_production' -and $c.database.user -eq 'leadconnect_backup' -and $c.database.sslmode -eq 'verify-full' -and $c.database.channel_binding -eq 'require') 'Metadata only; no connection made';AddCheck 'encrypted-keys' ((Test-Path $c.paths.encryptedCredentialFile) -and (Test-Path $c.paths.encryptedAesKeyFile)) 'DPAPI key files present';AddCheck 'drive-remote' ($c.paths.driveRemote -match ':Production_Database$') 'Configuration only; no Drive authorization or quota query';AddCheck 'scheduler' $true 'Preview definitions only; no task queried or created'}
$results|ConvertTo-Json -Depth 3; if(($results|Where-Object{-not $_.ok}).Count){exit 1}
